        for (File assetFolder : assetFolders) {
            checkAssets(context, assetFolder);
        }
    }

    private void checkAssets(@NonNull Context context, @NonNull File folder) {
        File[] files = folder.listFiles();
        if (files == null) return;
        for (File file : files) {
            if (file.isDirectory()) {
                checkAssets(context, file);
            } else if (isNativeLibrary(file)) {
                context.report(ISSUE, Location.create(file),
                        "Native code should not be placed in the assets directory; ...");
            }
        }
    }

    private boolean isNativeLibrary(@NonNull File file) {
        String name = file.getName();
        if (name.endsWith(".so")) return true;
        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] header = new byte[4];
            if (fis.read(header) == 4 && Arrays.equals(header, ELF_MAGIC)) return true;
        } catch (IOException e) {}
        return false;
    }
}
